insert into public.products(name,slug,sku,price,compare_price,description,images,tags,sizes,packs,category,concerns,tagline,top_ingredients,how_to_use,ingredients_raw,usp,benefits,captions,active,sort_order) values
  ('Advanced Hair Fortifying Oil 8% Allium Cepa Extract','advanced-hair-fortifying-oil-8-allium-cepa-extract','F50004',293,900,'A clinically formulated hair oil enriched with red onion extract, essential fatty acids, and powerful botanicals to strengthen roots, stimulate hair growth, and minimize breakage. This lightweight, non-greasy oil enhances scalp circulation and deeply nourishes follicles for thicker, healthier hair.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50004_main.png?v=1777618236','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50004m_2.png?v=1777618233','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50004_hero.png?v=1777617972','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50004_2.png?v=1777617827','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50004.png?v=1777617793']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":293,"mrp":900,"sku":"F50004"},{"n":2,"price":488,"mrp":1800,"sku":"F50004_2"},{"n":3,"price":634,"mrp":2700,"sku":"F50004_3"}]'::jsonb,'hair-care',array['hair-growth']::text[],'Stronger roots start here!',array['8% Allium Cepa Extract','10% Caprylic/Capric Triglyceride','10% Sesamum Indicum Seed Oil','10% Ricinus Communis Seed Oil','8% Prunus Dulcis Oil']::text[],'Part your hair and apply the oil directly to the scalp. Massage in circular motions to boost absorption. Leave on for a minimum of 2 hours or overnight for deep conditioning. Wash off with a mild shampoo. Use 2-3 times a week.','10% Caprylic/Capric Triglyceride + 10% Sesamum Indicum Seed Oil + 10% Ricinus Communis Seed Oil + 8% Prunus Dulcis Oil + 5% Oryza Sativa Bran Oil + 5% Simmondsia Chinensis Seed Oil + 8% Allium Cepa Extract + 5% Glycine Max Oil + 5% Macadamia Integrifolia Seed Oil + 5% Persea Gratissima Oil + 3% Avena Sativa Kernel Oil + 5% Eclipta Alba Extract + 2% Centella Asiatica Extract + 3% Murraya Koenigii Extract + 2% Bacopa Monnieri Extract + 5% Vitis Vinifera Seed Oil + 2% Triticum Vulgare Oil + 2% Rosa Canina Oil + 5% Aloe Barbadensis Leaf Extract + 2% Hibiscus Rosa-Sinensis Extract + 2% Tocopherol','Stronger roots start here!','',array['Stronger roots start here!,Infused with 8% Onion Extract + rich botanical oils, this formula deeply nourishes the scalp,Improves circulation & reduces hair fall,DM or shop now for thicker, healthier hair!','Hair fall? Not anymore!,Powered by Castor, Sesame & Eclipta oils to strengthen roots and boost regrowth,Lightweight, non-greasy daily care,Order now & transform your hair routine!','Revive weak roots naturally!,A nutrient-rich blend that enhances follicle strength & scalp health,Visible volume, shine & resilience,Buy now or DM us to get started!']::text[],true,0),
  ('Age-Defying Night Cream 10% Glycolic Acid','age-defying-night-cream-10-glycolic-acid','F50009',293,900,'A potent anti-aging formula enriched with glycolic acid and natural antioxidants to enhance collagen production, reduce wrinkles, and boost hydration for youthful, radiant skin.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50009_main.png?v=1777617825','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50009_m.png?v=1777618229','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50009.png?v=1777617816','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50009_1.png?v=1777617823']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":293,"mrp":900,"sku":"F50009"},{"n":2,"price":469,"mrp":1800,"sku":"F50009_2"},{"n":3,"price":615,"mrp":2700,"sku":"F50009_3"}]'::jsonb,'skincare',array['glow']::text[],'Wake up younger every day!',array['10% Glycolic Acid','Camellia Sinensis Extract','Persea Gratissima Oil','Algae Extracts']::text[],'Massage a pea-sized amount onto face and neck in upward motions. Use at night for best results. Follow with SPF during the day.','Glycolic Acid, Camellia Sinensis Extract, Persea Gratissima Oil, Algae Extracts','Wake up younger every day!','',array['Wake up younger every day!,Formulated with 10% Glycolic Acid + antioxidants to boost collagen,Smoothens texture & reduces fine lines overnight,DM to start your glow journey!','Turn back time while you sleep!,Gently exfoliates dead skin & improves elasticity,Hydrated, radiant skin by morning,Shop now for visible anti-aging results!','Night repair that works!,Targets wrinkles, dullness & uneven tone,Wake up to brighter, youthful skin,Order today & glow effortlessly!']::text[],true,1),
  ('Anti-Friction Barrier Cream 30% Cyclopentasiloxane','anti-friction-barrier-cream-30-cyclopentasiloxane','F50008',291,900,'A lightweight, non-greasy formula designed to prevent chafing, irritation, and discomfort caused by skin friction. Enriched with skin-conditioning agents, it provides a breathable barrier for all-day comfort.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50008_main.png?v=1777617821','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50008_2.png?v=1777617861','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50008_hero.png?v=1777617971','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50008.png?v=1777617807','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50008_1.png?v=1777617806']::text[],array[]::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":291,"mrp":900,"sku":"F50008"},{"n":2,"price":466,"mrp":1800,"sku":"F50008_2"},{"n":3,"price":611,"mrp":2700,"sku":"F50008_3"}]'::jsonb,'skincare',array['hydration']::text[],'No more chafing discomfort!',array['30% Cyclopentasiloxane','Dimethicone Crosspolymer','Vinyl Dimethicone Crosspolymer','Zea Mays Starch']::text[],'Massage gently onto areas prone to chafing, such as thighs, underarms, or other friction-prone areas. Reapply as needed.','Cyclopentasiloxane, Dimethicone Crosspolymer, Vinyl Dimethicone Crosspolymer, Zea Mays Starch','No more chafing discomfort!','',array['No more chafing discomfort!,With 30% Cyclopentasiloxane, forms a breathable protective layer,Perfect for workouts & daily wear,DM now for all-day comfort!','Stay comfortable, no matter what!,Prevents irritation in friction-prone areas,Smooth, non-sticky finish for daily use,Buy now & move freely!','Goodbye skin irritation!,Designed for active lifestyles & sensitive skin,Long-lasting protection & smoothness,Shop today & stay irritation-free!']::text[],true,2),
  ('Bone Strength Capsules 500mg Calcium','bone-strength-capsules-500mg-calcium','F50026',308,900,'A scientifically formulated calcium supplement enriched with essential minerals and vitamin D3 to promote bone density, strength, and long-term mobility.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50026_main.png?v=1777617756','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50026_main_1.png?v=1777617797','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50026_m.png?v=1777618235','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50026_1.png?v=1777618238']::text[],array[]::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":308,"mrp":900,"sku":"F50026"},{"n":2,"price":598,"mrp":1800,"sku":"F50026_2"},{"n":3,"price":778,"mrp":2700,"sku":"F50026_3"}]'::jsonb,'supplements',array['strength-energy']::text[],'Build stronger bones daily!',array['500mg Calcium Carbonate','Magnesium Oxide','Zinc Gluconate','Cholecalciferol','Menaquinone-7']::text[],'Consume one capsule with water after meals, or as directed by a healthcare professional. Maintain a healthy diet for optimal absorption.','Calcium Carbonate, Magnesium Oxide, Zinc Gluconate, Cholecalciferol, Menaquinone-7','Build stronger bones daily!','',array['Build stronger bones daily!,Enriched with Calcium, Magnesium & Vitamin D3 for better absorption,Supports density & joint flexibility,Order now for long-term strength!','Stay active, stay strong!,Promotes bone health & reduces weakness,Ideal for daily nutritional support,Shop now & move better!','Strength from within!,A complete mineral blend for bones & joints,Enhanced mobility & durability,DM to buy today!']::text[],true,3),
  ('Deep Clean Charcoal Tooth Powder 15% Activated Charcoal','deep-clean-charcoal-tooth-powder-15-activated-charcoal','F50017',249,800,'A fluoride-free, natural tooth powder infused with activated charcoal and calcium carbonate to deeply cleanse, whiten, and freshen breath.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50017_main.png?v=1777617787','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50017_2.png?v=1777617840','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50017.png?v=1777617755','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50017_1.png?v=1777617691']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":249,"mrp":800,"sku":"F50017"},{"n":2,"price":398,"mrp":1600,"sku":"F50017_2"},{"n":3,"price":523,"mrp":2400,"sku":"F50017_3"}]'::jsonb,'oral-care',array[]::text[],'Whiten naturally with every brush!',array['15% Activated Charcoal from Coconut','Calcium Carbonate','Sorbitol','Natural Spearmint Flavor','Stevia']::text[],'Use a small amount on a wet toothbrush and brush in circular motions for 2 minutes. Rinse thoroughly. Use 2-3 times a week.','Activated Charcoal from Coconut, Calcium Carbonate, Sorbitol, Natural Spearmint Flavor, Stevia','Whiten naturally with every brush!','',array['Whiten naturally with every brush!,15% Activated Charcoal removes deep stains & toxins,Fresh breath + stronger enamel,Buy now for a brighter smile!','Unlock your brightest smile!,Charcoal + Calcium cleanses & strengthens teeth,Removes yellow stains effectively,Shop today for natural whitening!','Detox your oral care routine!,Eliminates bad breath & impurities,Gentle yet powerful cleaning,DM us to order now!']::text[],true,4),
