  ('Exfoliating Coffee Face Scrub 15% Coffea Arabica Extract','exfoliating-coffee-face-scrub-15-coffea-arabica-extract','F50011',274,900,'A rejuvenating face scrub packed with green coffee, vitamin E & C, and activated charcoal to detoxify, brighten, and smooth skin texture. Removes dullness and impurities.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50011_main.png?v=1777617852','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50011.png?v=1777617871','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50011_hero.png?v=1777617973','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50011_2.png?v=1777617857','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50011_1.png?v=1777617851']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":274,"mrp":900,"sku":"F50011"},{"n":2,"price":438,"mrp":1800,"sku":"F50011_2"},{"n":3,"price":575,"mrp":2700,"sku":"F50011_3"}]'::jsonb,'skincare',array['glow','acne-cleansing']::text[],'Wake up your skin instantly!',array['15% Coffea Arabica Extract','Aloe Barbadensis Extract','Tocopherol','Simmondsia Chinensis Oil','Pterocarpus Santalinus Oil']::text[],'Apply to wet skin, gently exfoliate for 1-2 minutes, focusing on rough areas. Rinse with lukewarm water. Use 2-3 times a week.','Coffea Arabica Extract, Aloe Barbadensis Extract, Tocopherol, Simmondsia Chinensis Oil, Pterocarpus Santalinus Oil, Mel Extract, Activated Charcoal','Wake up your skin instantly!','',array['Wake up your skin instantly!,Infused with Coffee + Charcoal, removes dead skin & impurities,Boosts circulation for natural glow,Shop now for fresh skin!','Dull skin? Not anymore!,Gently exfoliates while nourishing with Vitamin E,Smooth, radiant texture after every use,Order today & glow brighter!','Scrub away tired skin!,Detoxifies pores & improves skin clarity,Perfect for weekly glow routine,DM now to buy!']::text[],true,7),
  ('Eye Revive Complex 10% Sodium Hyaluronate','eye-revive-complex-10-sodium-hyaluronate','F50005',211,500,'A revitalizing eye treatment infused with sodium hyaluronate, rosemary extract, and botanical hydrators to instantly brighten, firm, and de-puff the delicate under-eye area. This fast-absorbing formula deeply nourishes and reduces signs of fatigue, making your eyes appear refreshed and youthful.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005_main.png?v=1777617801','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005_1.png?v=1777617858','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005_hero.png?v=1777617968','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005_3.png?v=1777617860','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005_2.png?v=1777617870','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50005.png?v=1777617870']::text[],array['bestseller']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":211,"mrp":500,"sku":"F50005"},{"n":2,"price":290,"mrp":1000,"sku":"F50005_2"},{"n":3,"price":380,"mrp":1500,"sku":"F50005_3"}]'::jsonb,'skincare',array['dark-circles','hydration']::text[],'Goodbye dark circles!',array['10% Sodium Hyaluronate','40% Aqua','15% Glycerol','10% Propylene Glycol','10% Rosmarinus Officinalis Extract']::text[],'Apply directly under the eyes and gently pat in using your fingertips. Avoid rubbing the skin. Use morning and night for best results. For an added cooling effect, store in the refrigerator before application.','40% Aqua + 10% Propylene Glycol + 10% Sodium Hyaluronate + 15% Glycerol + 10% Rosmarinus Officinalis Extract + 5% Carbomer + 5% Lactose + 5% Cellulose','Goodbye dark circles!','',array['Goodbye dark circles!,With 10% Hyaluronic Acid, deeply hydrates & plumps under-eyes,Reduces puffiness & fatigue instantly,Buy now for brighter eyes!','Refresh tired eyes daily!,Botanical extracts soothe & rejuvenate delicate skin,Smooth, hydrated & youthful look,Shop today & feel the difference!','Bright eyes, bold confidence!,Targets dryness, fine lines & dullness,Perfect AM + PM routine,DM us to order!']::text[],true,8),
