  ('Radiance Boost Face Mask 10% Activated Charcoal','radiance-boost-face-mask-10-activated-charcoal','F50015',277,900,'A purifying and hydrating face mask that draws out impurities, minimizes pores, and refreshes the skin, leaving it radiant and smooth.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50015_main.png?v=1777617828','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50015_2.png?v=1777617748','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50015.png?v=1777617827','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50015_1.png?v=1777617872']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":277,"mrp":900,"sku":"F50015"},{"n":2,"price":443,"mrp":1800,"sku":"F50015_2"},{"n":3,"price":582,"mrp":2700,"sku":"F50015_3"}]'::jsonb,'skincare',array['glow','acne-cleansing']::text[],'Detox & glow instantly!',array['10% Activated Bamboo Charcoal','Purified Water','Xanthan Gum','Glycerin','Trehalose']::text[],'Spread evenly over cleansed face, avoiding the eye area. Leave on for 10-15 minutes, then rinse thoroughly. Use 2-3 times per week.','Purified Water, Xanthan Gum, Glycerin, Trehalose, Activated Bamboo Charcoal, Panthenol, Aloe Vera Extract, Sodium Hyaluronate, Sodium Benzoate, Potassium Sorbate, Phenoxyethanol, Disodium EDTA, Fragrance, Iron Oxide','Detox & glow instantly!','',array['Detox & glow instantly!,Charcoal clears pores deeply,Smooth, radiant skin,Buy now!','Clear skin therapy!,Removes toxins & excess oil,Brightens complexion,Shop today!','Glow boost in minutes!,Minimizes pores & refreshes,Weekly must-have,DM now!']::text[],true,21),
  ('Skin Recovery Cream 8% Paraffinum Liquidum','skin-recovery-cream-10-glycerin','F50014',368,900,'A powerful blend of hydrating and skin-repairing ingredients that fade scars, improve skin elasticity, and restore hydration, leaving skin smoother and healthier.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014_main.png?v=1777617848','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014_m.png?v=1777618239','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014_1.png?v=1777617869','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014_2_5879350a-90b1-47d9-bdbb-9a2e065df00b.png?v=1777617853','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014_2.png?v=1777617823','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50014.png?v=1777617821']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":368,"mrp":900,"sku":"F50014"},{"n":2,"price":589,"mrp":1800,"sku":"F50014_2"},{"n":3,"price":773,"mrp":2700,"sku":"F50014_3"}]'::jsonb,'skincare',array['hydration']::text[],'Repair your skin deeply!',array['8% Paraffinum Liquidum','Aqua','Glycerin','Cetearyl Alcohol','Cetyl Alcohol']::text[],'Use twice daily on clean, dry skin. Massage in circular motions until fully absorbed. For best results, use consistently over time.','Aqua, Glycerin, Paraffinum Liquidum, Cetearyl Alcohol, Cetyl Alcohol, Glyceryl Stearate SE, Alcohol','Repair your skin deeply!','',array['Repair your skin deeply!,Fades scars & stretch marks,Improves elasticity,Buy now!','Smooth skin journey!,Hydrates & restores texture,Daily repair care,Shop today!','Confidence restored!,Targets damaged skin effectively,Visible improvement,DM now!']::text[],true,22),
  ('Skin Renewal Serum 10% L-Ascorbic Acid','skin-renewal-serum-10-l-ascorbic-acid','F50002',382,900,'A high-performance Vitamin C serum designed to combat dullness, uneven skin tone, and early signs of aging. Infused with 10% L-Ascorbic Acid and hydrating agents, this serum enhances skin brightness, reduces dark spots, and supports collagen production for firmer, smoother skin. Lightweight and fast-absorbing, it is perfect for daily use.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50002_main.png?v=1777617806','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50002_2.png?v=1777617818','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50002_hero.png?v=1777617969','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50002_3.png?v=1777617801','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50002.png?v=1777617727']::text[],array['bestseller']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":382,"mrp":900,"sku":"F50002"},{"n":2,"price":611,"mrp":1800,"sku":"F50002_2"},{"n":3,"price":802,"mrp":2700,"sku":"F50002_3"}]'::jsonb,'skincare',array['glow']::text[],'Vitamin C glow boost!',array['10% L-Ascorbic Acid','55% Aqua','10% Propylene Glycol','5% Glycerin','5% Tocopherol']::text[],'After cleansing, apply 2-3 drops onto your fingertips and gently press into the skin, focusing on areas prone to dullness and pigmentation. Follow with a moisturizer and sunscreen during the day for maximum benefits. Use morning and night.','5% Glycerin + 3% Caffeine + 10% Propylene Glycol + 10% L-Ascorbic Acid + 5% Tocopherol + 2% Sodium Hyaluronate + 5% Sodium Methylparaben + 3% Sodium Propylparaben + 55% Aqua','Vitamin C glow boost!','',array['Vitamin C glow boost!,Brightens skin & reduces dark spots,Improves texture,Buy now!','Radiant skin daily!,Boosts collagen & smoothness,Even skin tone,Shop today!','Glow like never before!,Fights dullness & aging,Daily essential,DM now!']::text[],true,23),
  ('Strengthening Keratin Shampoo 10% Hydrolyzed Keratin','strengthening-keratin-shampoo-10-hydrolyzed-keratin','F50013',292,900,'A fortifying shampoo infused with hydrolyzed keratin and argan oil to restore hair strength, enhance shine, and prevent breakage. Leaves hair smooth and resilient.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50013_main.png?v=1777617750','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50013_2.png?v=1777617826','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50013.png?v=1777617832','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50013_1.png?v=1777617726']::text[],array['new']::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":292,"mrp":900,"sku":"F50013"},{"n":2,"price":467,"mrp":1800,"sku":"F50013_2"},{"n":3,"price":613,"mrp":2700,"sku":"F50013_3"}]'::jsonb,'hair-care',array['hair-growth']::text[],'Stronger hair with every wash!',array['10% Hydrolyzed Keratin','Aqua','Sodium Laureth Sulfate','Cocamide DEA','Cocamidopropyl Betaine']::text[],'Massage into the scalp and hair, lather for 1-2 minutes, then rinse with lukewarm water. Follow with a conditioner for best results.','Aqua, Sodium Laureth Sulfate, Cocamide DEA, Cocamidopropyl Betaine, Argania Spinosa Kernel Oil, Hydrolyzed Keratin, PEG-75 Lanolin, Sodium Benzoate, Disodium EDTA, Potassium Sorbate, Citric Acid, Alcohol Denat, Polyquaternium-7, Phenoxyethanol, Ethylhexylglycerin','Stronger hair with every wash!','',array['Stronger hair with every wash!,Keratin repairs damage deeply,Smooth & resilient strands,Buy now!','Hair repair formula!,Reduces breakage & dryness,Nourished scalp & hair,Shop today!','Healthy hair starts here!,Boosts strength & shine,Daily use shampoo,DM now!']::text[],true,24),
  ('Vital Mass Capsules 200mg Ashwagandha','vital-mass-capsules-200mg-ashwagandha','F50023',417,900,'A herbal supplement designed to improve appetite, boost metabolism, and promote healthy weight gain through adaptogenic and nutrient-rich ingredients.',array['https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50023_main.png?v=1777617806','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50023_1.png?v=1777618239','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50023_2.png?v=1777618232','https://cdn.shopify.com/s/files/1/0731/2303/7274/files/F50023_m.png?v=1777618211']::text[],array[]::text[],'{"1":50,"2":50,"3":50}'::jsonb,'[{"n":1,"price":417,"mrp":900,"sku":"F50023"},{"n":2,"price":667,"mrp":1800,"sku":"F50023_2"},{"n":3,"price":876,"mrp":2700,"sku":"F50023_3"}]'::jsonb,'supplements',array['strength-energy']::text[],'Power your workouts, naturally!',array['Withania Somnifera Extract','Asparagus Racemosus Extract','Pueraria Tuberosa Extract','Emblica Officinalis Extract','Tinospora Cordifolia Extract']::text[],'Consume one capsule daily or as directed by a healthcare professional. Pair with a balanced diet for optimal results.','Withania Somnifera Extract, Asparagus Racemosus Extract, Pueraria Tuberosa Extract, Emblica Officinalis Extract, Tinospora Cordifolia Extract','Power your workouts, naturally!','',array[]::text[],true,25)
